mapper.select:
SELECT a.user_id user_id, su.`name` user_name, IFNULL( SUM( a.inspection_quantity ), 0 ) inspection_quantity, IFNULL( SUM( b.qhse_quantity ), 0 ) qhse_quantity FROM mes_building_produce_inspection_team_report a LEFT JOIN mes_building_task task on a.task_id=task.id LEFT JOIN mes_building_produce_qhse_team_report b ON a.id = b.inspection_team_report_id LEFT JOIN sys_user su ON su.id = a.user_id
a.bool_delete_enum = FALSE
AND task.project_id in
#{projectId}
AND task.project_id=#{projectId}
AND a.in_year_month_day_date >= date_format(#{startDate}, '%Y-%m-%d')
AND a.in_year_month_day_date <= date_format(#{endDate}, '%Y-%m-%d')
AND a.task_type_enum&#{productType}
GROUP BY a.user_id

SELECT task.project_id 'project.id', task.monomer_id 'monomer.id', task.area_id 'areaDetail.id', cp.`name` 'project.name', cp.short_name 'project.short_name', cp.serial_number 'project.serial_number', pm.`name` 'monomer.name', pd.`name` 'areaDetail.name', DATE( a.create_time ) date, a.process_id, process.`name` process_name, CASE a.task_type_enum WHEN 2 THEN artifact.`name` ELSE enclosure.`name` END NAME, CASE a.task_type_enum WHEN 1 THEN machine_part.serial_number WHEN 2 THEN artifact.serial_number WHEN 16 THEN assemble.serial_number ELSE enclosure.serial_number END serial_number, IFNULL( sum( a.inspection_quantity ), 0 ) inspection_quantity, IFNULL( sum( b.qhse_quantity ), 0 ) qhse_quantity FROM mes_building_produce_inspection_team_report a LEFT JOIN mes_building_produce_qhse_team_report b ON a.id = b.inspection_team_report_id LEFT JOIN mes_building_process process ON a.process_id = process.id LEFT JOIN mes_building_task task ON a.task_id = task.id LEFT JOIN contract_project cp ON cp.id = task.project_id LEFT JOIN plan_monomer pm ON pm.id = task.monomer_id LEFT JOIN plan_area pd ON pd.id = task.area_id LEFT JOIN tech_artifact artifact ON a.product_id = artifact.id LEFT JOIN tech_assemble assemble ON a.product_id = assemble.id LEFT JOIN tech_enclosure enclosure ON a.product_id = enclosure.id LEFT JOIN tech_machine_part machine_part ON a.product_id = machine_part.id
AND task.project_id in
#{projectId}
AND a.process_id=#{processId}
AND task.project_id=#{projectId}
AND DATE(a.create_time)>=DATE(#{startDate})
AND DATE(a.create_time)<=DATE(#{endDate})
AND a.task_type_enum&#{productType}
AND cp.`name` like CONCAT('%', #{projectName},'%')
AND ( artifact.serial_number LIKE CONCAT( '%', #{serialNumber}, '%' ) OR assemble.serial_number LIKE CONCAT( '%', #{serialNumber}, '%' ) OR enclosure.serial_number LIKE CONCAT( '%', #{serialNumber}, '%' ) OR machine_part.serial_number LIKE CONCAT( '%', #{serialNumber}, '%' ) )
AND a.user_id = #{userId}
GROUP BY task.project_id, task.monomer_id, task.area_id, cp.`name`, cp.short_name, cp.serial_number, pm.`name`, pd.`name`, DATE ( a.create_time ), a.process_id, process.`name`, a.task_type_enum, machine_part.serial_number, artifact.serial_number, assemble.serial_number, enclosure.serial_number, artifact.`name`, enclosure.`name` order by qhse_quantity desc

SELECT a.*, rep.number FROM( SELECT task.project_id 'project.id', task.monomer_id 'monomer.id', task.area_id 'areaDetail.id', cp.`name` 'project.name', cp.short_name 'project.short_name', cp.serial_number 'project.serial_number', pm.`name` 'monomer.name', pd.`name` 'areaDetail.name', DATE ( a.create_time ) DATE, a.process_id, a.inspect_report_number, process.`name` process_name, CASE a.task_type_enum WHEN 2 THEN artifact.`name` END NAME, CASE a.task_type_enum WHEN 2 THEN artifact.serial_number WHEN 16 THEN assemble.serial_number END serial_number, IFNULL( sum( a.inspection_quantity ), 0 ) inspection_quantity, IFNULL( sum( b.qhse_quantity ), 0 ) qhse_quantity FROM mes_building_produce_inspection_team_report a LEFT JOIN mes_building_produce_qhse_team_report b ON a.id = b.inspection_team_report_id LEFT JOIN mes_building_process process ON a.process_id = process.id LEFT JOIN mes_building_task task ON a.task_id = task.id LEFT JOIN contract_project cp ON cp.id = task.project_id LEFT JOIN plan_monomer pm ON pm.id = task.monomer_id LEFT JOIN plan_area pd ON pd.id = task.area_id LEFT JOIN tech_artifact artifact ON a.product_id = artifact.id LEFT JOIN tech_assemble assemble ON a.product_id = assemble.id
a.bool_delete_enum = 0
AND task.project_id in
#{projectId}
AND a.process_id=#{processId}
AND task.project_id=#{projectId}
AND a.in_year_month_day_date >= date_format(#{startDate}, '%Y-%m-%d')
AND a.in_year_month_day_date <= date_format(#{endDate}, '%Y-%m-%d')
AND a.task_type_enum& 18
AND cp.`name` like CONCAT('%', #{projectName},'%')
AND ( artifact.serial_number LIKE CONCAT( '%', #{serialNumber}, '%' ) OR assemble.serial_number LIKE CONCAT( '%', #{serialNumber}, '%' ) )
AND a.user_id = #{userId}
GROUP BY task.project_id, task.monomer_id, task.area_id, cp.`name`, cp.short_name, cp.serial_number, pm.`name`, pd.`name`, DATE ( a.create_time ), a.process_id, a.inspect_report_number, process.`name`, a.task_type_enum, artifact.serial_number, assemble.serial_number, artifact.`name` ) a LEFT JOIN mes_building_produce_inspection_team_report rep ON a.inspect_report_number = rep.inspect_report_number AND a.inspection_quantity = 1 and rep.bool_delete_enum = 0 ORDER BY a.qhse_quantity DESC
